import { dayNumber } from "./quotes";

/**
 * The daily puzzle. 365 short tactics from the Lichess puzzle database (CC0, database.lichess.org), picked for
 * rating 850–1700, high popularity and many plays, then checked move by move with chess.js when the list was built:
 * mate in 1, mate in 2, and "find the best move" puzzles of one or two moves, mixed through the week.
 *
 * `fen` is the position the solver sees (the opponent's last move already played), `moves` the solution in UCI:
 * the solver's move, the reply, the solver's move … `alt` lists other mating moves that also finish a mate puzzle.
 * Server-only by use: pages hand today's puzzle to the client component, never the whole list.
 */
export interface Puzzle {
  id: string;
  fen: string;
  moves: string[];
  rating: number;
  goal: "mate1" | "mate2" | "best";
  alt?: string[];
}

