/** Today's puzzle in club time: it changes at midnight in Berlin, like the quote of the day. */
export function puzzleOfTheDay(now: Date = new Date()): Puzzle {
  return PUZZLES[dayNumber(now) % PUZZLES.length];
}

/** The puzzle on Lichess, for "open on Lichess" (analysis, other lines). */
export function lichessPuzzleUrl(p: Puzzle): string {
  return `https://lichess.org/training/${p.id}`;
}
